#ifndef CODEC_RUNTIME_UNICODE_CLASS_H
#define CODEC_RUNTIME_UNICODE_CLASS_H

#include <cstddef>
#include <cstdint>
#include <string>

// Codepoint classes of the HF `tokenizers` Whitespace pre-tokenizer
// (`\w+|[^\w\s]+`), generated by scripts/gen-unicode-class.py.
bool codec_unicode_is_word(uint32_t cp);
bool codec_unicode_is_space(uint32_t cp);

// Decode the UTF-8 sequence at `s[*pos]` and advance `*pos` past it.  An
// invalid or truncated sequence consumes one byte and yields U+FFFD.
inline uint32_t codec_utf8_next(const std::string & s, size_t * pos) {
    const size_t n = s.size();
    const unsigned char c = (unsigned char) s[*pos];
    int len = c < 0x80 ? 1 : (c >> 5) == 0x6 ? 2 : (c >> 4) == 0xE ? 3 : (c >> 3) == 0x1E ? 4 : 0;
    if (len == 0 || *pos + len > n) { ++*pos; return 0xFFFD; }
    uint32_t cp = len == 1 ? c : len == 2 ? (c & 0x1F) : len == 3 ? (c & 0x0F) : (c & 0x07);
    for (int k = 1; k < len; ++k) {
        const unsigned char cc = (unsigned char) s[*pos + k];
        if ((cc >> 6) != 0x2) { ++*pos; return 0xFFFD; }
        cp = (cp << 6) | (cc & 0x3F);
    }
    *pos += len;
    return cp;
}

#endif
